/// Where the new project templates are.
const TEMPLATES: &str = "project-templates";

/// Each template folder in `project-templates`, as a `(key, manifest, files)`
/// entry holding its template.json and, relative to its spec folder, every
/// file in that, each built in with `include_str!`.
fn embed_templates() {
    println!("cargo:rerun-if-changed={TEMPLATES}");
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join(TEMPLATES);
    let mut templates: Vec<_> = std::fs::read_dir(&root)
        .unwrap_or_else(|err| panic!("could not read {TEMPLATES}: {err}"))
        .filter_map(|entry| entry.ok().map(|entry| entry.path()))
        .filter(|path| path.is_dir())
        .collect();
    templates.sort();

    let mut code = String::from(
        "// Generated by build.rs from project-templates. Don't edit.\\npub static TEMPLATES: &[(&str, &str, &[(&str, &str)])] = &[\\n",
    );
    for template in templates {
        let key = template.file_name().unwrap().to_string_lossy().into_owned();
        let manifest = template.join("template.json");
        assert!(manifest.is_file(), "{} has no template.json", template.display());
        let mut files = Vec::new();
        collect_files(&template.join("spec"), &template.join("spec"), &mut files);
        files.sort();
        writeln!(code, "    ({key:?}, include_str!({:?}), &[", manifest.display().to_string()).unwrap();
        for (relative, path) in files {
            writeln!(code, "        ({relative:?}, include_str!({:?})),", path.display().to_string()).unwrap();
        }
        code.push_str("    ]),\\n");
    }
    code.push_str("];\\n");
    let out = Path::new(&std::env::var("OUT_DIR").unwrap()).join("project_templates.rs");
    std::fs::write(out, code).expect("could not write the project templates");
}

/// Every file under `dir`, with its path relative to `base` using `/`.
fn collect_files(base: &Path, dir: &Path, files: &mut Vec<(String, std::path::PathBuf)>) {
